 <PageTitle>ShipmentTracker – Track Your Shipment</PageTitle>

 <div class="container py-5">
     <div class="text-center mb-5">
         <h1 class="display-4">📦 Shipment Tracker</h1>
         <p class="lead text-body-secondary">Enter your tracking number to check your shipment status.</p>
     </div>

     <div class="row justify-content-center">
         <div class="col-md-8 col-lg-6">
             <div class="input-group input-group-lg mb-3">
                 <input type="text" class="form-control" placeholder="e.g. SHP-2026-001"
                        @bind="trackingNumber" @bind:event="oninput"
                        @onkeydown="HandleKeyDown" />
                 <button class="btn btn-primary" @onclick="SearchShipment" disabled="@isLoading">
                     @if (isLoading)
                     {
                         <span class="spinner-border spinner-border-sm me-1"></span>
                     }
                     Track
                 </button>
             </div>

             @if (searched && shipment is null && !isLoading)
             {
                 <div class="alert alert-warning">
                     <strong>Not found.</strong> No shipment matches tracking number "<strong>@searchedTracking</strong>".
                 </div>
             }

             @if (shipment is not null)
             {
                 <div class="card shadow-sm">
                     <div class="card-header d-flex justify-content-between align-items-center">
                         <strong>@shipment.TrackingNumber</strong>
                         <span class="badge @GetStatusBadgeClass(shipment.Status)">@shipment.Status</span>
                     </div>
                     <div class="card-body">
                         <dl class="row mb-0">
                             <dt class="col-sm-5">From</dt>
                             <dd class="col-sm-7">@shipment.Origin</dd>

                             <dt class="col-sm-5">To</dt>
                             <dd class="col-sm-7">@shipment.Destination</dd>

                             <dt class="col-sm-5">Recipient</dt>
                             <dd class="col-sm-7">@shipment.RecipientName</dd>

                             <dt class="col-sm-5">Shipped</dt>
                             <dd class="col-sm-7">@shipment.ShippedDate.ToString("MMM dd, yyyy")</dd>

                             <dt class="col-sm-5">Est. Delivery</dt>
                             <dd class="col-sm-7">@shipment.EstimatedDelivery.ToString("MMM dd, yyyy")</dd>

                             @if (shipment.ActualDelivery.HasValue)
                             {
                                 <dt class="col-sm-5">Delivered</dt>
                                 <dd class="col-sm-7">@shipment.ActualDelivery.Value.ToString("MMM dd, yyyy")</dd>
                             }

                             <dt class="col-sm-5">Description</dt>
                             <dd class="col-sm-7">@shipment.Description</dd>
                         </dl>
                     </div>
                 </div>
             }
         </div>
     </div>
 </div>

 @code {
     private string trackingNumber = string.Empty;
     private string searchedTracking = string.Empty;
     private ShipmentDto? shipment;
     private bool isLoading;
     private bool searched;

     private async Task SearchShipment()
     {
         if (string.IsNullOrWhiteSpace(trackingNumber))
             return;

         isLoading = true;
         searched = true;
         searchedTracking = trackingNumber.Trim();
         shipment = null;

         try
         {
             shipment = await ShipmentService.GetShipmentByTrackingAsync(searchedTracking);
         }
         finally
         {
             isLoading = false;
         }
     }

     private async Task HandleKeyDown(KeyboardEventArgs e)
     {
         if (e.Key == "Enter")
             await SearchShipment();
     }

     private static string GetStatusBadgeClass(ShipmentStatus status) => status switch
     {
         ShipmentStatus.Delivered => "bg-success",
         ShipmentStatus.InTransit => "bg-primary",
         ShipmentStatus.OutForDelivery => "bg-info text-dark",
         ShipmentStatus.Pending => "bg-secondary",
         ShipmentStatus.Delayed => "bg-warning text-dark",
         ShipmentStatus.Cancelled => "bg-danger",
         _ => "bg-secondary"
     };
 }

